	@Test
	void defaultParserAcceptsReferencesInSubjectObjectAndValues() {
		ParsedQuery parsed = parser.parseQuery(
				"SELECT ?value WHERE { <_:subject> <urn:p> <_:object> . VALUES ?value { <_:value> } }", null);

		List<StatementPattern> patterns = new ArrayList<>();
		List<BindingSetAssignment> values = new ArrayList<>();
		parsed.getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				patterns.add(node);
			}

			@Override
			public void meet(BindingSetAssignment node) {
				values.add(node);
			}
		});

		assertThat(patterns).hasSize(1);
		assertThat(patterns.get(0).getSubjectVar().getValue())
				.isEqualTo(SimpleValueFactory.getInstance().createBNode("subject"));
		assertThat(patterns.get(0).getObjectVar().getValue())
				.isEqualTo(SimpleValueFactory.getInstance().createBNode("object"));
		assertThat(values).hasSize(1);
		assertThat(values.get(0).getBindingSets()).hasSize(1);
		assertThat(values.get(0).getBindingSets().iterator().next().getValue("value"))
				.isEqualTo(SimpleValueFactory.getInstance().createBNode("value"));
	}

	@Test
	void referenceEscapesDecodeOnceWithoutRetokenizing() {
		ParsedQuery parsed = parser.parseQuery(
				"SELECT ?value WHERE { VALUES ?value { <_:a\\u003Eb\\u005Cu0062> } }", null);

		List<BindingSetAssignment> values = new ArrayList<>();
		parsed.getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				values.add(node);
			}
		});

		assertThat(values).hasSize(1);
		Value value = values.get(0).getBindingSets().iterator().next().getValue("value");
		assertThat(value).isEqualTo(SimpleValueFactory.getInstance().createBNode("a>b\\u0062"));
	}

