	@Test
	void parseOperationDispatchesVersionQueriesAndUpdatesForBothOptionPolicies() {
		String query = "VERSION '1.2'\r\n# prologue comment\r\nBASE <urn:base:>\r\n"
				+ "PREFIX ex: <urn:example:>\r\nSELECT * WHERE { ex:s ex:p ?o }";
		String update = "VERSION \"1.2\"\r\n# prologue comment\r\nBASE <urn:base:>\r\n"
				+ "PREFIX ex: <urn:example:>\r\nINSERT DATA { ex:s ex:p ex:o }";
		for (QueryParseOptions options : List.of(QueryParseOptions.DEFAULT, QueryParseOptions.STRICT)) {
			assertThat(QueryParserUtil.parseOperation(QueryLanguage.SPARQL, query, null))
					.isInstanceOf(ParsedTupleQuery.class);
			assertThat(QueryParserUtil.parseOperation(QueryLanguage.SPARQL, query, null, options))
					.isInstanceOf(ParsedTupleQuery.class);
			assertThat(QueryParserUtil.parseOperation(QueryLanguage.SPARQL, update, null))
					.isInstanceOf(ParsedUpdate.class);
			assertThat(QueryParserUtil.parseOperation(QueryLanguage.SPARQL, update, null, options))
					.isInstanceOf(ParsedUpdate.class);
		}
	}

	@Test
	void referenceGroundInsertAndDeleteDataAreAccepted() {
		ParsedUpdate insert = parser.parseUpdate("INSERT DATA { <_:subject> <urn:p> <_:object> }", null);
		ParsedUpdate delete = parser.parseUpdate("DELETE DATA { <_:subject> <urn:p> <_:object> }", null);

		assertThat(insert.getUpdateExprs()).hasSize(1);
		assertThat(delete.getUpdateExprs()).hasSize(1);
	}

